// Extract and parse the campaign_context JSON from the OpenAI node output.

function stripFences(text) {
  let t = (text || '').trim();
  if (t.startsWith('```')) {
    const first = t.indexOf('\n');
    const last  = t.lastIndexOf('```');
    if (first !== -1 && last > first) t = t.slice(first + 1, last).trim();
  }
  return t;
}

const raw = $json?.output?.[0]?.content?.[0]?.text || '';

let parsed = {};
try {
  parsed = JSON.parse(stripFences(raw));
} catch {}

if (parsed && Object.keys(parsed).length > 0) {
  return { json: { campaign_context: parsed } };
}

if ($json?.campaign_context) {
  return { json: { campaign_context: $json.campaign_context } };
}

return { json: { campaign_context: $json } };

const nodeJson = $input.first().json;

const outputText =
  (nodeJson.output &&
    nodeJson.output[0] &&
    nodeJson.output[0].content &&
    nodeJson.output[0].content[0] &&
    nodeJson.output[0].content[0].text) ||
  '';

let data = {};
try {
  let t = outputText.trim();
  if (t.startsWith('```')) {
    const first = t.indexOf('\n');
    const last  = t.lastIndexOf('```');
    if (first !== -1 && last > first) t = t.slice(first + 1, last).trim();
  }
  data = JSON.parse(t);
} catch (e) {
  data = {};
}

const contextItem = $items('Store Campaign Context')[0] || { json: {} };
const context = contextItem.json.campaign_context || {};

return [
  {
    json: {
      campaign_context: context,
      linkedin_prompt_generated: data.linkedin_prompt || '',
      email_prompt_generated: data.email_prompt || '',
      blog_prompt_generated: data.blog_prompt || '',
      image_prompt_generated: data.image_prompt || '',
    },
  },
];

