const binaries = items[0].binary;

return Object.keys(binaries).map(key => ({
  binary: {
    data: binaries[key]
  }
}));

const cleanText = (text) => {
  if (!text || typeof text !== "string") return "";
  return text
    .replace(/\r\n/g, "\n")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
};

const files = items[0].json.files || [];

const documents = files.map((file, index) => {
  const title = file.metadata?.fileName || `Document_${index + 1}`;
  const content = cleanText(file.text);
  return { title, content };
});

const combined = documents
  .map(doc => `===== ${doc.title} =====\n${doc.content}`)
  .join("\n\n");

return [
  {
    json: {
      documents,
      combined_text: combined
    }
  }
];

// === Build Final Report ===

function textFromOpenAI(item) {
  if (!item || !item.json) return '';
  return item.json?.output?.[0]?.content?.[0]?.text || item.json?.text || '';
}

function parseJson(raw) {
  if (!raw || typeof raw !== 'string') return {};
  let t = raw.trim();
  if (t.startsWith('```')) {
    const first = t.indexOf('\n');
    const last  = t.lastIndexOf('```');
    if (first !== -1 && last > first) t = t.slice(first + 1, last).trim();
  }
  try { return JSON.parse(t); } catch { return {}; }
}

function scoreBar(score) {
  const pct = Math.min(100, Math.round(score > 1 ? score * 10 : score * 100));
  const color = pct >= 75 ? '#22c55e' : pct >= 50 ? '#f59e0b' : '#ef4444';
  return `<div style="background:#e5e7eb;border-radius:999px;height:8px;width:100%;margin-top:4px">
    <div style="background:${color};width:${pct}%;height:8px;border-radius:999px"></div>
  </div><small style="color:${color};font-weight:600">${pct}/100</small>`;
}

function mdToHtml(text) {
  return (text || '')
    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
    .replace(/\*(.+?)\*/g, '<em>$1</em>')
    .replace(/^[-•]\s+/gm, '&bull; ');
}

// --- Pull data ---
let ctx = {};
try { ctx = $items('Store Campaign Context')[0]?.json?.campaign_context || {}; } catch {}

const linkedinDraft = textFromOpenAI($items('LinkedIn Generator')[0]);

const emailData    = parseJson(textFromOpenAI($items('Email Generator')[0]));
let emailSubject   = emailData.email_subject || '';
let emailBody      = emailData.email_body    || '';

const blogData   = parseJson(textFromOpenAI($items('Blog Generator')[0]));
let blogTitle    = blogData.blog_title || '';
let blogBody     = blogData.blog_body  || '';

let linkedin   = linkedinDraft;
let wasRevised = false;

try {
  const improveItems = $items('Auto-Improve Content');
  if (improveItems.length > 0) {
    const imp = parseJson(textFromOpenAI(improveItems[0]));
    if (imp.linkedin_post_final)  { linkedin     = imp.linkedin_post_final;  wasRevised = true; }
    if (imp.email_subject_final)  { emailSubject = imp.email_subject_final;  wasRevised = true; }
    if (imp.email_body_final)     { emailBody    = imp.email_body_final;     wasRevised = true; }
    if (imp.blog_title_final)     { blogTitle    = imp.blog_title_final;     wasRevised = true; }
    if (imp.blog_body_final)      { blogBody     = imp.blog_body_final;      wasRevised = true; }
  }
} catch {}

let scoring = {};
try { scoring = parseJson(textFromOpenAI($items('Judge & Score Content')[0])); } catch {}

const nl2br = (s) => (s || '').replace(/\n/g, '<br>');
const date  = new Date().toLocaleDateString('en-GB', { day:'numeric', month:'long', year:'numeric' });

const html = `<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<style>
  body { font-family: 'Segoe UI', Arial, sans-serif; background: #f8fafc; margin: 0; padding: 32px; color: #1e293b; }
  .wrapper { max-width: 860px; margin: auto; }
  .header { background: linear-gradient(135deg,#0f172a,#1d4ed8); color:#fff; border-radius:16px; padding:36px 40px; margin-bottom:32px; }
  .header h1 { margin:0 0 6px; font-size:28px; }
  .header p  { margin:0; opacity:.75; font-size:14px; }
  .badge { display:inline-block; background:rgba(255,255,255,.15); border-radius:999px; padding:4px 14px; font-size:12px; margin-top:14px; margin-right:6px; }
  .card { background:#fff; border-radius:14px; padding:28px 32px; margin-bottom:24px; box-shadow:0 1px 4px rgba(0,0,0,.07); }
  .card h2 { margin:0 0 18px; font-size:16px; text-transform:uppercase; letter-spacing:.07em; color:#64748b; display:flex; align-items:center; gap:8px; }
  .card h2 span { font-size:20px; }
  .card p { margin:0; line-height:1.75; font-size:15px; white-space:pre-wrap; word-break:break-word; }
  .subject-line { background:#f1f5f9; border-left:4px solid #1d4ed8; padding:10px 16px; border-radius:0 8px 8px 0; font-weight:600; margin-bottom:16px; }
  .score-row { display:flex; justify-content:space-between; flex-wrap:wrap; gap:16px; }
  .score-card { flex:1; min-width:180px; background:#f8fafc; border-radius:10px; padding:16px 20px; }
  .score-card h3 { margin:0 0 6px; font-size:13px; color:#64748b; text-transform:uppercase; letter-spacing:.05em; }
  .suggestions { margin-top:10px; padding-left:16px; font-size:13px; color:#475569; }
  .suggestions li { margin-bottom:4px; }
  .footer { text-align:center; font-size:12px; color:#94a3b8; margin-top:32px; }
</style>
</head>
<body>
<div class="wrapper">
  <div class="header">
    <h1>${ctx.feature_name || 'Product Feature'} &mdash; Marketing Campaign</h1>
    <p>${ctx.product || 'Genie AI'} &bull; Generated on ${date}</p>
    <span class="badge">${ctx.audience?.role || 'B2B Audience'}</span>
    ${wasRevised ? '<span class="badge" style="background:rgba(250,204,21,.25)">AI-Revised</span>' : ''}
  </div>

  <div class="card">
    <h2><span>💼</span> LinkedIn Post</h2>
    <p>${nl2br(mdToHtml(linkedin))}</p>
  </div>

  <div class="card">
    <h2><span>📧</span> Email Campaign</h2>
    <div class="subject-line">Subject: ${emailSubject}</div>
    <p>${nl2br(mdToHtml(emailBody))}</p>
  </div>

  <div class="card">
    <h2><span>📝</span> Blog Post</h2>
    <p><strong>${blogTitle}</strong></p><br>
    <p>${nl2br(mdToHtml(blogBody))}</p>
  </div>

  <div class="card">
    <h2><span>📊</span> Quality Scores</h2>
    <div class="score-row">
      ${['linkedin','email','blog'].map(ch => {
        const s = scoring[ch] || {};
        const verdict = s.verdict === 'pass'
          ? '<span style="color:#22c55e;font-weight:600">✔ Pass</span>'
          : '<span style="color:#f59e0b;font-weight:600">&#8635; Revised</span>';
        const suggestions = (s.suggestions || []).map(x => `<li>${x}</li>`).join('');
        return `<div class="score-card">
          <h3>${ch.charAt(0).toUpperCase()+ch.slice(1)}</h3>
          ${verdict}
          ${scoreBar(s.score)}
          ${suggestions ? `<ul class="suggestions">${suggestions}</ul>` : ''}
        </div>`;
      }).join('')}
    </div>
  </div>

  <div class="footer">Generated by Genie AI Marketing Agent &bull; ${date}</div>
</div>
</body>
</html>`;

return [{ json: { report_html: html } }];
